----batch party profile
UPDATE ui.dashboardquery SET
vcdashboardquery =  E'{ 	
    "Account": {
             "Monthly": "WITH  RECURSIVE profile AS ( SELECT pv.iaccountid, pv.tdate, pv.val || cast( format( ''{\\"Address\\":\\"%s\\",\\"Name\\":\\"%s\\", \\"Last Update\\":\\"%s\\"}'', vcexternalaccountid, vcaccountname, COALESCE(TO_CHAR(last_updated, ''YYYY-MM-DD\\"T\\"HH24:MI:SSOF''), ''1970-01-01T00:00:00+00:00'')) as jsonb) as val FROM profiles.account_monthly pv LEFT JOIN masters.accounts v ON v.iaccountid = pv.iaccountid and v.itenantid=:tenantid WHERE tdate BETWEEN cast(:StartDate as date) AND cast(:EndDate as date) - 1 AND v.vcexternalaccountid = :Address ), flat (iaccountid, tdate, key, value) AS ( SELECT iaccountid, tdate, concat('''', key), value FROM profile, jsonb_each(val) UNION SELECT iaccountid, tdate, concat(f.key, ''.'', j.key), j.value FROM flat f, jsonb_each(f.value) j WHERE jsonb_typeof(f.value) = ''object'' ) SELECT cast(json_agg(data) as text) FROM ( SELECT iaccountid, tdate, jsonb_object_agg( COALESCE(metadata.vccolumnname, flat.key), value ) AS data FROM flat LEFT JOIN profiles.metadata ON metadata.vcpath = flat.key AND metadata.vcroot = ''account_monthly'' AND metadata.itenantid=:tenantid WHERE jsonb_typeof(value) <> ''object'' GROUP BY iaccountid, tdate ) a limit 1000;",
            "Weekly": "WITH  RECURSIVE profile AS ( SELECT pv.iaccountid, pv.tdate, pv.val || cast( format( ''{\\"Address\\":\\"%s\\",\\"Name\\":\\"%s\\", \\"Last Update\\":\\"%s\\"}'', vcexternalaccountid, vcaccountname, COALESCE(TO_CHAR(last_updated, ''YYYY-MM-DD\\"T\\"HH24:MI:SSOF''), ''1970-01-01T00:00:00+00:00'')) as jsonb) as val FROM profiles.account_weekly pv LEFT JOIN masters.accounts v ON v.iaccountid = pv.iaccountid and v.itenantid=:tenantid WHERE tdate BETWEEN cast(:StartDate as date) AND cast(:EndDate as date) - 1 AND v.vcexternalaccountid = :Address ), flat (iaccountid, tdate, key, value) AS ( SELECT iaccountid, tdate, concat('''', key), value FROM profile, jsonb_each(val) UNION SELECT iaccountid, tdate, concat(f.key, ''.'', j.key), j.value FROM flat f, jsonb_each(f.value) j WHERE jsonb_typeof(f.value) = ''object'' ) SELECT cast(json_agg(data) as text) FROM ( SELECT iaccountid, tdate, jsonb_object_agg( COALESCE(metadata.vccolumnname, flat.key), value ) AS data FROM flat LEFT JOIN profiles.metadata ON metadata.vcpath = flat.key AND metadata.vcroot = ''account_weekly'' AND metadata.itenantid=:tenantid WHERE jsonb_typeof(value) <> ''object'' GROUP BY iaccountid, tdate ) a limit 1000;"
         },
         "VPA": {
             "Monthly": "WITH RECURSIVE profile AS ( SELECT pv.ivpaid, pv.tdate, pv.val || cast( format( ''{\\"Address\\":\\"%s\\",\\"Name\\":\\"%s\\", \\"Last Update\\":\\"%s\\"}'', vcexternaladdressid, vcvpaname, COALESCE(TO_CHAR(last_updated, ''YYYY-MM-DD\\"T\\"HH24:MI:SSOF''), ''1970-01-01T00:00:00+00:00'')) as jsonb) as val FROM profiles.vpa_monthly pv LEFT JOIN masters.vpa v ON v.ivpaid = pv.ivpaid and v.itenantid=:tenantid WHERE tdate BETWEEN cast(:StartDate as date) AND cast(:EndDate as date) - 1 AND v.vcexternaladdressid = :Address ), flat (ivpaid, tdate, key, value) AS ( SELECT ivpaid, tdate, concat('''', key), value FROM profile, jsonb_each(val) UNION SELECT ivpaid, tdate, concat(f.key, ''.'', j.key), j.value FROM flat f, jsonb_each(f.value) j WHERE jsonb_typeof(f.value) = ''object'' ) SELECT cast(json_agg(data) as text) FROM ( SELECT ivpaid, tdate, jsonb_object_agg( COALESCE(metadata.vccolumnname, flat.key), value ) AS data FROM flat LEFT JOIN profiles.metadata ON metadata.vcpath = flat.key AND metadata.vcroot = ''vpa_monthly'' AND metadata.itenantid=:tenantid WHERE jsonb_typeof(value) <> ''object'' GROUP BY ivpaid, tdate ) a limit 1000;",
            "Weekly": "WITH RECURSIVE profile AS ( SELECT pv.ivpaid, pv.tdate, pv.val || cast( format( ''{\\"Address\\":\\"%s\\",\\"Name\\":\\"%s\\", \\"Last Update\\":\\"%s\\"}'', vcexternaladdressid, vcvpaname, COALESCE(TO_CHAR(last_updated, ''YYYY-MM-DD\\"T\\"HH24:MI:SSOF''), ''1970-01-01T00:00:00+00:00'')) as jsonb) as val FROM profiles.vpa_weekly pv LEFT JOIN masters.vpa v ON v.ivpaid = pv.ivpaid and v.itenantid=:tenantid WHERE tdate BETWEEN cast(:StartDate as date) AND cast(:EndDate as date) - 1 AND v.vcexternaladdressid = :Address ), flat (ivpaid, tdate, key, value) AS ( SELECT ivpaid, tdate, concat('''', key), value FROM profile, jsonb_each(val) UNION SELECT ivpaid, tdate, concat(f.key, ''.'', j.key), j.value FROM flat f, jsonb_each(f.value) j WHERE jsonb_typeof(f.value) = ''object'' ) SELECT cast(json_agg(data) as text) FROM ( SELECT ivpaid, tdate, jsonb_object_agg( COALESCE(metadata.vccolumnname, flat.key), value ) AS data FROM flat LEFT JOIN profiles.metadata ON metadata.vcpath = flat.key AND metadata.vcroot = ''vpa_weekly'' AND metadata.itenantid=:tenantid WHERE jsonb_typeof(value) <> ''object'' GROUP BY ivpaid, tdate ) a limit 1000;"
         }
     }
'::text WHERE
idashboardqueryid = 65 AND itenantid = 8;

