        "Account": {
             "Monthly": "WITH  RECURSIVE profile AS ( SELECT pv.iaccountid, pv.tdate, pv.val || cast( format( ''{\\"Address\\":\\"%s\\",\\"Name\\":\\"%s\\", \\"Last Update\\":\\"%s\\"}'', vcexternalaccountid, vcaccountname, last_updated ) as jsonb ) as val FROM profiles.account_monthly pv LEFT JOIN masters.accounts v ON v.iaccountid = pv.iaccountid and v.itenantid=:tenantid WHERE tdate BETWEEN cast(:StartDate as date) AND cast(:EndDate as date) - 1 AND v.vcexternalaccountid = :Address ), flat (iaccountid, tdate, key, value) AS ( SELECT iaccountid, tdate, concat('''', key), value FROM profile, jsonb_each(val) UNION SELECT iaccountid, tdate, concat(f.key, ''.'', j.key), j.value FROM flat f, jsonb_each(f.value) j WHERE jsonb_typeof(f.value) = ''object'' ) SELECT cast(json_agg(data) as text) FROM ( SELECT iaccountid, tdate, jsonb_object_agg( COALESCE(metadata.vccolumnname, flat.key), value ) AS data FROM flat LEFT JOIN profiles.metadata ON metadata.vcpath = flat.key AND metadata.vcroot = ''account_monthly'' AND metadata.itenantid=:tenantid WHERE jsonb_typeof(value) <> ''object'' GROUP BY iaccountid, tdate ) a limit 1000;",
           "Weekly": "WITH  RECURSIVE profile AS ( SELECT pv.iaccountid, pv.tdate, pv.val || cast( format( ''{\\"Address\\":\\"%s\\",\\"Name\\":\\"%s\\", \\"Last Update\\":\\"%s\\"}'', vcexternalaccountid, vcaccountname, last_updated ) as jsonb ) as val FROM profiles.account_weekly pv LEFT JOIN masters.accounts v ON v.iaccountid = pv.iaccountid and v.itenantid=:tenantid WHERE tdate BETWEEN cast(:StartDate as date) AND cast(:EndDate as date) - 1 AND v.vcexternalaccountid = :Address ), flat (iaccountid, tdate, key, value) AS ( SELECT iaccountid, tdate, concat('''', key), value FROM profile, jsonb_each(val) UNION SELECT iaccountid, tdate, concat(f.key, ''.'', j.key), j.value FROM flat f, jsonb_each(f.value) j WHERE jsonb_typeof(f.value) = ''object'' ) SELECT cast(json_agg(data) as text) FROM ( SELECT iaccountid, tdate, jsonb_object_agg( COALESCE(metadata.vccolumnname, flat.key), value ) AS data FROM flat LEFT JOIN profiles.metadata ON metadata.vcpath = flat.key AND metadata.vcroot = ''account_weekly'' AND metadata.itenantid=:tenantid WHERE jsonb_typeof(value) <> ''object'' GROUP BY iaccountid, tdate ) a limit 1000;"
        },
        "VPA": {
             "Monthly": "WITH RECURSIVE profile AS ( SELECT pv.ivpaid, pv.tdate, pv.val || cast( format( ''{\\"Address\\":\\"%s\\",\\"Name\\":\\"%s\\", \\"Last Update\\":\\"%s\\"}'', vcexternaladdressid, vcvpaname, last_updated ) as jsonb ) as val FROM profiles.vpa_monthly pv LEFT JOIN masters.vpa v ON v.ivpaid = pv.ivpaid and v.itenantid=:tenantid WHERE tdate BETWEEN cast(:StartDate as date) AND cast(:EndDate as date) - 1 AND v.vcexternaladdressid = :Address ), flat (ivpaid, tdate, key, value) AS ( SELECT ivpaid, tdate, concat('''', key), value FROM profile, jsonb_each(val) UNION SELECT ivpaid, tdate, concat(f.key, ''.'', j.key), j.value FROM flat f, jsonb_each(f.value) j WHERE jsonb_typeof(f.value) = ''object'' ) SELECT cast(json_agg(data) as text) FROM ( SELECT ivpaid, tdate, jsonb_object_agg( COALESCE(metadata.vccolumnname, flat.key), value ) AS data FROM flat LEFT JOIN profiles.metadata ON metadata.vcpath = flat.key AND metadata.vcroot = ''vpa_monthly'' AND metadata.itenantid=:tenantid WHERE jsonb_typeof(value) <> ''object'' GROUP BY ivpaid, tdate ) a limit 1000;",
           "Weekly": "WITH RECURSIVE profile AS ( SELECT pv.ivpaid, pv.tdate, pv.val || cast( format( ''{\\"Address\\":\\"%s\\",\\"Name\\":\\"%s\\", \\"Last Update\\":\\"%s\\"}'', vcexternaladdressid, vcvpaname, last_updated ) as jsonb ) as val FROM profiles.vpa_weekly pv LEFT JOIN masters.vpa v ON v.ivpaid = pv.ivpaid and v.itenantid=:tenantid WHERE tdate BETWEEN cast(:StartDate as date) AND cast(:EndDate as date) - 1 AND v.vcexternaladdressid = :Address ), flat (ivpaid, tdate, key, value) AS ( SELECT ivpaid, tdate, concat('''', key), value FROM profile, jsonb_each(val) UNION SELECT ivpaid, tdate, concat(f.key, ''.'', j.key), j.value FROM flat f, jsonb_each(f.value) j WHERE jsonb_typeof(f.value) = ''object'' ) SELECT cast(json_agg(data) as text) FROM ( SELECT ivpaid, tdate, jsonb_object_agg( COALESCE(metadata.vccolumnname, flat.key), value ) AS data FROM flat LEFT JOIN profiles.metadata ON metadata.vcpath = flat.key AND metadata.vcroot = ''vpa_weekly'' AND metadata.itenantid=:tenantid WHERE jsonb_typeof(value) <> ''object'' GROUP BY ivpaid, tdate ) a limit 1000;"
        }
    }'::text WHERE
idashboardqueryid = 65 and itenantid in (21,22,23,17,16);

---reports
--pendency report

UPDATE ui.dashboardquery SET
vcdashboardquery = 'SELECT string_agg (DISTINCT grp.name_, '', '') as "Group Name",
cuser.email_ as "Analyst Name",
count(distinct CASE
WHEN DATE_PART(''day'', current_timestamp -  CASE
WHEN  oplog.timestamp_ is not null THEN oplog.timestamp_
WHEN  oplog.timestamp_ is null THEN task.create_time_
ELSE null END ) > 30 THEN task.proc_inst_id_
ELSE null
END) as "Above 30 days",
count(distinct CASE
WHEN DATE_PART(''day'', current_timestamp -  CASE
WHEN  oplog.timestamp_ is not null THEN oplog.timestamp_
WHEN  oplog.timestamp_ is null THEN task.create_time_
ELSE null END ) between 20 and 30 THEN task.proc_inst_id_
ELSE null
END) as "30 days to 20 days",
count(distinct CASE
WHEN DATE_PART(''day'', current_timestamp -  CASE
WHEN  oplog.timestamp_ is not null THEN oplog.timestamp_
WHEN  oplog.timestamp_ is null THEN task.create_time_
ELSE null END ) between 10 and 20 THEN task.proc_inst_id_
ELSE null
END) as "20 days to 10 days",
count(distinct CASE
WHEN DATE_PART(''day'', current_timestamp -  CASE
WHEN  oplog.timestamp_ is not null THEN oplog.timestamp_
WHEN  oplog.timestamp_ is null THEN task.create_time_
ELSE null END ) < 10 THEN task.proc_inst_id_
ELSE null
END) as "below 10 days"
FROM
camunda.act_ru_task task
right join camunda.act_re_procdef pdef on task.proc_def_id_ = pdef.id_
full outer join camunda.act_hi_identitylink oplog on oplog.id_ = (select id_ from camunda.act_hi_identitylink where task_id_ = task.id_ and type_ = ''assignee'' and user_id_ = task.assignee_ order by timestamp_ desc limit 1)
right join camunda.act_id_user cuser on task.assignee_ = cuser.id_
right join camunda.act_id_membership memb on task.assignee_ = memb.user_id_
right join camunda.act_hi_identitylink idl on idl.task_id_ = task.id_ and idl.type_= ''candidate''
left join camunda.act_id_group grp on grp.id_ = idl.group_id_ and grp.id_ = memb.group_id_
where task.assignee_ is not null and task.tenant_id_ = :tenantidstr
group by cuser.id_
order by string_agg(DISTINCT grp.name_, '', '') asc limit 1000'::text WHERE
idashboardqueryid = 59 and itenantid in (21,22,23,17,16);

---case summary

UPDATE ui.dashboardquery SET
vcdashboardquery =  E'{
